// Clean the AI output: strip markdown code blocks and extract valid JSON
let rawOutput = $input.first().json.output;

// Remove markdown code block wrappers if present
rawOutput = rawOutput.trim();

// Strip ```json ... ``` or ``` ... ``` wrappers
if (rawOutput.startsWith('```')) {
  rawOutput = rawOutput.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '');
}

// Try to extract JSON object from the string
const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('No valid JSON object found in AI response');
}

let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  throw new Error('Failed to parse JSON from AI response: ' + e.message);
}

// Validate required fields
if (!parsed.questions || !Array.isArray(parsed.questions)) {
  throw new Error('AI response missing "questions" array');
}

return {
  json: {
    success: true,
    generatedQuestions: parsed
  }
};
